    "duration": "90 minutes, adaptable to two 45-minute lessons",
    "prerequisites": [
      "Basic programming concepts: variables, loops, conditions, and functions",
      "Familiarity with zero-based indexing is helpful but not required",
      "No prior knowledge of pointers or references is required"
    ],
    "teaching_objectives": {
      "knowledge": [
        "Define an array and a linked list and describe how each organizes elements.",
        "Explain indices, contiguous storage, nodes, head references, next links, and null termination.",
        "State the typical time complexity of access, search, insertion, and deletion, including important assumptions."
      ],
      "skills": [
        "Draw and trace the state of an array and a singly linked list after basic operations.",
        "Traverse a linked list and correctly insert a node after a known node.",
        "Compare arrays and linked lists and justify a suitable choice for a given application."
      ],
      "higher_order_thinking": [
        "Evaluate the claim that linked-list insertion is always faster than array insertion.",
        "Recognize that data-structure performance depends on the operation, available references, and implementation."
      ],
      "learning_success_criteria": [
        "Correctly trace at least 80 percent of the practice operations.",
        "Complete a comparison table without confusing indexed access with search.",
        "Give a scenario-based recommendation that identifies at least one relevant trade-off."
      ]
    },
    "key_points": [
      {
        "point": "Memory organization",
        "explanation": "Arrays typically store elements in a contiguous block and use indices for direct access. Linked lists store nodes that may be noncontiguous, with links connecting one node to another."
      },
      {
        "point": "Access patterns",
        "explanation": "An array supports O(1) access by a valid index. A singly linked list normally requires O(n) traversal to reach an element by position or value."
      },
      {
        "point": "Structural modification",
        "explanation": "Inserting or deleting inside an array may require shifting elements. A linked list changes links instead, but locating the affected position may still require traversal."
      },
      {
        "point": "Trade-offs rather than a universal winner",
        "explanation": "The appropriate structure depends on access frequency, modification patterns, memory considerations, and implementation constraints."
      }
    ],
    "difficulties": [
      {
        "difficulty": "Understanding links and node identity",
        "common_misconception": "Students may believe linked-list elements are stored in consecutive positions or can be accessed directly using an index.",
        "teaching_strategy": "Use separate node cards connected by removable arrows. Emphasize that the head reference and next links are the only routes used during traversal."
      },
      {
        "difficulty": "Correctly updating links",
        "common_misconception": "Students may overwrite prev.next before saving the remainder of the list.",
        "teaching_strategy": "Trace one pointer update at a time and require students to draw the list after every assignment."
      },
      {
        "difficulty": "Qualifying Big-O statements",
        "common_misconception": "Students may state that every linked-list insertion or deletion is O(1).",
        "teaching_strategy": "Separate locating a position from performing the modification. Link updates are O(1) when the required node or predecessor is already known; finding it can take O(n)."
      },
      {
        "difficulty": "Distinguishing arrays from dynamic arrays",
        "common_misconception": "Students may assume that all arrays can grow instantly and without cost.",
        "teaching_strategy": "Briefly explain that a basic fixed-size array has fixed capacity. A dynamic array may resize by allocating and copying, making append amortized O(1), with an occasional O(n) resize."
      }
    ],
