        "essential_ideas": [
          "Traversal starts at the head and repeatedly follows next links.",
          "Nodes do not need to occupy consecutive memory locations.",
          "Each node requires additional storage for its link."
        ],
        "insert_after_pseudocode": [
          "insert_after(prev, value):",
          "    if prev is null: report an error",
          "    new_node = Node(value)",
          "    new_node.next = prev.next",
          "    prev.next = new_node"
