        "expected_output": "Correct before-and-after diagrams and the insertion pseudocode.",
        "assessment": "Check whether students can identify what happens when the head reference is lost."
      },
      {
        "activity": "4. Guided Complexity Comparison",
        "time": "15 minutes",
        "purpose": "Develop accurate, conditional Big-O statements.",
        "teacher_actions": [
          "Provide an incomplete comparison table.",
          "Ask students to justify each entry using shifts, traversal, or link updates.",
          "Challenge the statement that linked lists are always better for insertion."
        ],
        "student_actions": [
          "Complete the table in small groups.",
          "Add assumptions such as unsorted data or a known predecessor."
        ],
        "expected_output": "A completed table with at least two qualifications to oversimplified complexity claims.",
        "assessment": "Listen for confusion between O(1) modification and O(n) location."
