{
  "title": "Advanced Topics in Algebraic Geometry: Schemes",
  "course_level": "Graduate or advanced undergraduate mathematics",
  "unit_overview": "This unit introduces schemes as locally ringed spaces that generalize classical algebraic varieties and unify algebraic geometry with commutative algebra and arithmetic. Students progress from affine spectra and structure sheaves to morphisms, gluing, projective schemes, fiber products, and the functor-of-points viewpoint.",
  "duration": {
    "sessions": 4,
    "minutes_per_session": 90,
    "total_minutes": 360
  },
  "conventions": "All rings are commutative with identity, and all ring homomorphisms preserve the identity. Unless otherwise stated, k denotes a field.",
  "prerequisites": [
    "Commutative algebra: prime and maximal ideals, radicals, localization, quotient rings, and tensor products",
    "Basic point-set topology, including bases for a topology and continuous maps",
    "Basic category theory: objects, morphisms, universal properties, and natural bijections",
    "Elementary sheaf theory is helpful; a short review should be provided if necessary",
    "Familiarity with classical affine or projective varieties is recommended but not required"
  ],
  "teaching_objectives": [
    {
      "id": "O1",
      "objective": "Construct Spec A as a topological space and compute its points, closed sets, and principal open sets in concrete examples.",
      "evidence_of_learning": "Students correctly analyze Spec Z, Spec C[x], and principal open sets such as D(6) and D(x)."
    },
    {
      "id": "O2",
      "objective": "Explain the structure sheaf of an affine scheme and calculate sections and stalks using localization.",
      "evidence_of_learning": "Students use O(D(f)) ≅ A_f and O_{Spec A,p} ≅ A_p in explicit computations."
    },
    {
      "id": "O3",
      "objective": "Define schemes and their morphisms and explain the contravariant correspondence between rings and affine schemes.",
      "evidence_of_learning": "Students convert ring homomorphisms into morphisms of affine schemes and compute the induced map on prime ideals."
    },
    {
      "id": "O4",
      "objective": "Use gluing data to construct schemes and explain why a scheme contains more information than its underlying topological space.",
      "evidence_of_learning": "Students compare gluing constructions for the projective line and the line with a doubled origin, and distinguish Spec k from Spec k[ε]/(ε²)."
    },
    {
      "id": "O5",
      "objective": "Compute elementary fiber products and interpret them as base change or scheme-theoretic fibers.",
      "evidence_of_learning": "Students use Spec A ×_{Spec C} Spec B ≅ Spec(A ⊗_C B) in concrete calculations."
    },
    {
      "id": "O6",
      "objective": "Communicate rigorous geometric arguments using definitions, examples, counterexamples, and universal properties.",
      "evidence_of_learning": "Students produce a short written or oral synthesis connecting algebraic data with geometric constructions."
    }
  ],
  "key_points": [
    {
      "point": "Affine spectra",
      "details": "The points of Spec A are prime ideals of A. Closed sets have the form V(I) = {p : I ⊆ p}, and the sets D(f) = {p : f ∉ p} form a basis for the Zariski topology."
    },
