{
  "teaching_material": {
    "title": "Advanced Algorithms: Graph Theory and Network Flow",
    "target_learners": "Advanced undergraduate or beginning graduate students in computer science, mathematics, or related disciplines",
    "duration": {
      "classroom_time": "Two 90-minute sessions",
      "optional_programming_lab": "60 minutes"
    },
    "prerequisites": [
      "Basic graph terminology, including vertices, edges, paths, cycles, and connectivity",
      "Breadth-first search and depth-first search",
      "Asymptotic time and space complexity",
      "Basic proof techniques, especially induction and contradiction",
      "Programming experience in Python, Java, or C++"
    ],
    "teaching_objectives": [
      {
        "id": "O1",
        "objective": "Construct appropriate graph or flow-network models for algorithmic problems.",
        "evidence_of_learning": "Students define vertices, edges, weights or capacities, source and sink vertices, and explain how a solution to the model solves the original problem."
      },
      {
        "id": "O2",
        "objective": "Select graph algorithms according to problem structure and analyze their complexity.",
        "evidence_of_learning": "Students distinguish requirements for topological sorting, shortest-path algorithms, strongly connected components, and minimum spanning trees, and justify their algorithm choices."
      },
      {
        "id": "O3",
        "objective": "Explain feasible flows, residual networks, augmenting paths, and the need for reverse residual arcs.",
        "evidence_of_learning": "Students correctly update a residual network, including an augmentation that cancels flow on a previously used edge."
      },
      {
        "id": "O4",
        "objective": "Apply the Ford-Fulkerson method and the Edmonds-Karp algorithm to compute maximum flow.",
        "evidence_of_learning": "Students trace augmentations, calculate bottleneck capacities, verify capacity and conservation constraints, and state the relevant running-time bounds."
      },
      {
        "id": "O5",
        "objective": "Use the max-flow min-cut theorem to certify optimality.",
        "evidence_of_learning": "Students extract an s-t cut from the final residual network and demonstrate that the flow value equals the cut capacity."
      },
      {
        "id": "O6",
        "objective": "Reduce applications such as bipartite matching and vertex-capacitated routing to network flow.",
        "evidence_of_learning": "Students construct a valid reduction and prove that its maximum-flow value corresponds to the required application quantity."
      }
    ],
    "key_points": [
      {
        "topic": "Graph representation and algorithm selection",
        "details": "Adjacency lists normally use O(V + E) space and suit sparse graphs; adjacency matrices use O(V²) space and support constant-time edge queries. Algorithm choice must account for directedness, cycles, edge weights, negative weights, and graph density."
      },
      {
        "topic": "Structural graph reasoning",
        "details": "Topological ordering applies to directed acyclic graphs. Strongly connected components can be contracted to form a condensation DAG. Dijkstra's algorithm requires nonnegative edge weights, whereas Bellman-Ford supports negative weights and detects reachable negative cycles."
      },
      {
        "topic": "Flow feasibility",
        "details": "A feasible flow satisfies 0 ≤ f(u,v) ≤ c(u,v) for every edge and flow conservation at every vertex other than the source s and sink t. The flow value is the net flow leaving s."
      },
      {
        "topic": "Residual networks and augmentation",
        "details": "A residual network records remaining forward capacity and the ability to reduce existing flow through reverse residual arcs. An augmenting path increases the flow value by its bottleneck residual capacity."
      },
      {
        "topic": "Max-flow min-cut duality",
        "details": "Every feasible flow value is at most the capacity of every s-t cut. The maximum-flow value equals the minimum s-t cut capacity. Cut capacity includes only original edges directed from the source side S to the sink side T."
      },
      {
        "topic": "Algorithms and complexity",
        "details": "Ford-Fulkerson is a method whose running time depends on the augmentation strategy. Edmonds-Karp chooses a shortest augmenting path using BFS and runs in O(VE²). Dinic's algorithm uses level graphs and blocking flows, with a general bound of O(V²E)."
      }
    ],
    "difficulties": [
      {
        "difficulty": "Understanding reverse residual arcs",
        "common_misconception": "Students treat a reverse residual arc as a new physical edge or assume that residual paths must also be paths in the original network.",
        "teaching_strategy": "Use a small network in which the first augmentation makes a locally reasonable but globally restrictive choice. Require students to complete a second augmentation that cancels the earlier choice."
      },
      {
        "difficulty": "Connecting termination with optimality",
        "common_misconception": "Students believe that the absence of an obvious augmenting path is sufficient without examining the complete residual network.",
        "teaching_strategy": "Define S as all vertices reachable from s in the final residual network. Show why crossing edges are saturated or carry no opposing flow and why the resulting cut certifies optimality."
      },
      {
        "difficulty": "Distinguishing flows from cuts",
        "common_misconception": "Students minimize the number of cut edges, include edges from T to S in cut capacity, or assume that the maximum-flow assignment and minimum cut must be unique.",
        "teaching_strategy": "Contrast flow conservation with directed cut capacity and provide examples having multiple maximum flows or multiple minimum cuts."
      },
      {
        "difficulty": "Constructing correct reductions",
        "common_misconception": "Students build a network that produces a numerical answer but cannot explain why every feasible application solution corresponds to a feasible flow and vice versa.",
        "teaching_strategy": "Require a two-direction correspondence argument and an explanation of how integral capacities produce an integral solution."
      }
    ],
    "core_content_outline": [
      {
        "module": "Algorithmic graph modeling",
        "topics": [
          "Directed and undirected graphs, weighted graphs, DAGs, and multigraphs",
          "Adjacency-list and adjacency-matrix trade-offs",
          "Transforming application constraints into vertices, edges, weights, and capacities"
        ]
      },
      {
        "module": "Graph algorithm reference",
        "algorithms": [
          {
            "problem": "Unweighted reachability or minimum number of edges",
            "algorithm": "BFS",
            "typical_complexity": "O(V + E)"
          },
          {
            "problem": "Dependency ordering",
            "algorithm": "Topological sort after verifying that the graph is a DAG",
            "typical_complexity": "O(V + E)"
          },
          {
            "problem": "Strong connectivity in directed graphs",
            "algorithm": "Tarjan's or Kosaraju's algorithm",
            "typical_complexity": "O(V + E)"
          },
          {
            "problem": "Single-source shortest paths with nonnegative weights",
            "algorithm": "Dijkstra's algorithm with a binary heap",
            "typical_complexity": "O((V + E) log V)"
          },
          {
            "problem": "Single-source shortest paths with possible negative weights",
            "algorithm": "Bellman-Ford",
            "typical_complexity": "O(VE)"
          },
          {
            "problem": "Minimum spanning tree of a connected undirected weighted graph",
            "algorithm": "Kruskal's or Prim's algorithm",
            "typical_complexity": "Kruskal: O(E log E); Prim with a binary heap: O((V + E) log V)"
          }
        ]
      },
      {
        "module": "Network flow",
        "topics": [
          "Capacity constraints, conservation, flow value, and residual capacity",
          "Augmenting paths and bottleneck capacity",
          "Ford-Fulkerson, Edmonds-Karp, and an introduction to Dinic's algorithm",
          "s-t cuts, weak duality, and the max-flow min-cut theorem",
          "Integral maximum flows for networks with integral capacities"
        ]
      },
      {
        "module": "Flow modeling and extensions",
        "topics": [
          "Bipartite matching through source-to-left, left-to-right, and right-to-sink edges",
          "Multiple sources or sinks through super-source and super-sink vertices",
          "Vertex capacities through vertex splitting",
          "Optional extensions: lower bounds, circulations, and minimum-cost flow"
        ]
      }
    ],
    "worked_flow_example": {
      "purpose": "Demonstrate why reverse residual arcs are necessary.",
      "network": {
        "vertices": ["s", "a", "b", "t"],
        "edges": [
          {"from": "s", "to": "a", "capacity": 1},
          {"from": "s", "to": "b", "capacity": 1},
          {"from": "a", "to": "b", "capacity": 1},
          {"from": "a", "to": "t", "capacity": 1},
          {"from": "b", "to": "t", "capacity": 1}
        ]
      },
      "steps": [
        "First augment along s → a → b → t with bottleneck 1. The flow value becomes 1.",
        "In the residual network, augment along s → b → a → t with bottleneck 1. The arc b → a is a reverse residual arc and cancels the previous flow on a → b.",
        "The final flows are f(s,a) = 1, f(s,b) = 1, f(a,b) = 0, f(a,t) = 1, and f(b,t) = 1.",
        "No s-t path remains in the residual network."
      ],
      "result": {
        "maximum_flow_value": 2,
        "minimum_cut": {
          "S": ["s"],
          "T": ["a", "b", "t"],
          "forward_cut_edges": ["s → a", "s → b"],
          "capacity": 2
        },
        "optimality_certificate": "The flow value 2 equals the cut capacity 2, so the flow is maximum and the cut is minimum."
      }
    },
    "classroom_activity_design": {
      "session_1": {
        "theme": "Graph modeling, structure, and algorithm selection",
        "activities": [
          {
            "time": "0-10 minutes",
            "activity": "Diagnostic problem hook",
            "teacher_actions": "Present a scenario combining task dependencies, weighted routes, and delivery capacities. Ask which parts are naturally modeled as graphs and which require flow networks.",
            "student_actions": "Individually sketch a model and then compare assumptions with a partner.",
            "evidence_of_learning": "Students identify appropriate graph features and reveal prerequisite misconceptions."
          },
          {
            "time": "10-30 minutes",
            "activity": "Targeted mini-lesson",
            "teacher_actions": "Review representations, DAGs, strongly connected components, shortest-path preconditions, and complexity trade-offs using contrasting examples.",
            "student_actions": "Annotate an algorithm-selection table and ask clarification questions.",
            "evidence_of_learning": "Students can state not only an algorithm but also why its preconditions hold."
          },
          {
            "time": "30-55 minutes",
            "activity": "Algorithm-selection clinic",
            "teacher_actions": "Give each team four problem cards involving dependency ordering, nonnegative shortest paths, negative edge weights, and strong connectivity.",
            "student_actions": "For each card, select an algorithm, identify invalid alternatives, state complexity, and specify the required graph representation.",
            "evidence_of_learning": "Each team submits a four-row decision table with justifications."
          },
          {
            "time": "55-80 minutes",
            "activity": "Jigsaw reasoning workshop",
            "teacher_actions": "Assign half the teams a Dijkstra counterexample involving a negative edge and the other half an SCC condensation task. Provide prompts about invariants and DAG structure.",
            "student_actions": "Solve the assigned task, then explain it to a team that solved the other task.",
            "evidence_of_learning": "Explanations identify why Dijkstra's settled-distance invariant can fail or why an SCC condensation must be acyclic."
          },
          {
            "time": "80-90 minutes",
            "activity": "Team report and exit ticket",
            "teacher_actions": "Address one recurring error and ask students to write the most important precondition for one selected algorithm.",
            "student_actions": "Submit a concise justification rather than only an algorithm name.",
            "evidence_of_learning": "Exit tickets provide evidence for grouping and review in the next session."
          }
        ]
      },
      "session_2": {
        "theme": "Residual networks, maximum flow, and minimum cuts",
        "activities": [
          {
            "time": "0-10 minutes",
            "activity": "Retrieval warm-up and feasible-flow check",
            "teacher_actions": "Display a small network containing one proposed feasible flow and one proposal violating conservation.",
            "student_actions": "Check capacity and conservation constraints and calculate the feasible flow's value.",
            "evidence_of_learning": "Students use formal constraints rather than visual intuition."
          },
          {
            "time": "10-30 minutes",
            "activity": "Residual-network mini-lesson",
            "teacher_actions": "Introduce forward and reverse residual capacities, bottleneck augmentation, and the distinction between Ford-Fulkerson and Edmonds-Karp.",
            "student_actions": "Update one residual edge at a time and predict the effect of cancelling flow.",
            "evidence_of_learning": "Students correctly explain that a reverse residual arc represents rerouting flexibility."
          },
          {
            "time": "30-55 minutes",
            "activity": "Augmenting-path relay using the worked example",
            "teacher_actions": "Assign roles for path finding, residual updating, feasibility checking, and recording. Rotate roles after each augmentation.",
            "student_actions": "Perform both augmentations, including s → b → a → t, and explain why the final flow is feasible.",
            "evidence_of_learning": "Teams produce a complete residual trace and a flow table with maximum-flow value 2."
          },
          {
            "time": "55-70 minutes",
            "activity": "Min-cut proof sketch",
            "teacher_actions": "Guide students to define S as the vertices reachable from s in the final residual network and develop the weak-duality argument.",
            "student_actions": "Compute the example cut and reconstruct why equality certifies optimality.",
            "evidence_of_learning": "Students can state the proof outline without relying on a particular diagram."
          },
          {
            "time": "70-85 minutes",
            "activity": "Bipartite-matching modeling challenge",
            "teacher_actions": "Present a small applicant-job instance and require capacities that enforce at most one assignment per applicant and per job.",
            "student_actions": "Build the network, explain the integral-flow correspondence, and identify the matching obtained from a maximum flow.",
            "evidence_of_learning": "The submitted model includes both the construction and a short correctness argument."
          },
          {
            "time": "85-90 minutes",
            "activity": "Exit ticket",
            "teacher_actions": "Ask how to construct a minimum cut after no augmenting path remains.",
            "student_actions": "Answer in three or four sentences.",
            "evidence_of_learning": "A complete answer mentions residual reachability, equality of flow value and cut capacity, and weak duality."
          }
        ]
      }
    },
    "optional_programming_lab": {
      "task": "Implement Edmonds-Karp using BFS on a residual graph with paired forward and reverse arcs.",
      "input": "A directed network with integral capacities, a source s, and a sink t; parallel edges should be supported.",
      "required_output": [
        "The maximum-flow value",
        "The final flow on each original edge",
        "The set S of vertices reachable from s in the final residual network",
        "The capacity of the resulting s-t cut"
      ],
      "validation_requirements": [
        "Check capacity constraints and flow conservation.",
        "Verify that the computed flow value equals the reported cut capacity.",
        "Test the worked example, for which the expected maximum flow is 2.",
        "Test a network with edges s → a of capacity 3, s → b of capacity 2, a → b of capacity 1, a → t of capacity 2, and b → t of capacity 2; the expected maximum flow is 4.",
        "Test a disconnected network, for which the expected maximum flow is 0."
      ],
      "analysis_requirement": "Explain why BFS augmentation gives the O(VE²) bound and identify the implementation's additional space usage."
    },
    "assessment": {
      "formative_assessment": [
        "Diagnostic modeling sketch",
        "Algorithm-selection decision table",
        "Residual-network trace checked by peers",
        "Flow-versus-cut questioning during the proof activity",
        "Session exit tickets"
      ],
      "exit_ticket_answer_key": [
        {
          "question": "Why can Dijkstra's algorithm fail when a negative edge is present?",
          "expected_answer": "A vertex marked as settled may later receive a shorter path through the negative edge, invalidating the algorithm's central invariant."
        },
        {
          "question": "How does the final residual network certify a maximum flow?",
          "expected_answer": "Let S contain all vertices reachable from s. Since t is unreachable, S and its complement form an s-t cut. At termination, the flow value equals this cut's capacity; weak duality therefore proves that the flow is maximum and the cut is minimum."
        }
      ],
      "performance_rubric": [
        {"criterion": "Graph or flow modeling and representation", "points": 15},
        {"criterion": "Algorithm selection, preconditions, and complexity", "points": 20},
        {"criterion": "Flow feasibility and residual-network tracing", "points": 25},
        {"criterion": "Max-flow min-cut reasoning and correctness arguments", "points": 20},
        {"criterion": "Implementation, testing, and clarity of communication", "points": 20}
      ]
    },
    "homework_and_extensions": [
      "Prove that the standard unit-capacity flow reduction for bipartite matching produces a maximum matching, using integrality in both directions of the correspondence.",
      "Explain how to model a vertex with capacity k by splitting it into two vertices, and state which edges should receive capacity k.",
      "Construct a network having more than one maximum-flow assignment and determine whether its minimum cut is unique.",
      "Implement Dinic's algorithm or compare its level-graph and blocking-flow ideas with Edmonds-Karp.",
      "Advanced extension: investigate circulation with lower bounds or successive shortest paths for minimum-cost flow."
